#include <pthread.h>
#include <semaphore.h>

#define CAP 1
#define N_PRODUCER 1
#define N_CONSUMER 1
#define PER 12

sem_t empty, full, mutex;
int buffer[CAP];
int head = 0, tail = 0;

void *producer(void *arg) {
    int pid = *(int *)arg;
    for (int i = 0; i < PER; i++) {
        sem_wait(&empty);        /* P(empty)：等空槽（同步） */
        sem_wait(&mutex);        /* P(mutex)：互斥访问缓冲区   */
        buffer[tail] = pid;      /* 临界区：放入产品           */
        tail = (tail + 1) % CAP;
        sem_post(&mutex);        /* V(mutex) */
        sem_post(&full);         /* V(full)：通知消费者         */
    }
    return NULL;
}

void *consumer(void *arg) {
    for (int i = 0; i < PER; i++) {
        sem_wait(&full);         /* P(full)：等产品（同步）     */
        sem_wait(&mutex);        /* P(mutex)：互斥访问缓冲区   */
        int item = buffer[head]; /* 临界区：取出产品           */
        head = (head + 1) % CAP;
        sem_post(&mutex);        /* V(mutex) */
        sem_post(&empty);        /* V(empty)：通知生产者        */
        (void)item;
    }
    return NULL;
}

int main(void) {
    sem_init(&empty, 0, CAP);
    sem_init(&full,  0, 0);
    sem_init(&mutex, 0, 1);
    /* 省略 pthread_create / pthread_join 等线程创建与回收代码 */
    return 0;
}
